import { batchUrlUpdates, useUrlState } from '@pyreon/url-state'

const Catalogue = () => {
  const f = useUrlState({ q: '', sort: 'name', inStock: false })
  const page = useUrlState('page', 1)

  const search = (q: string) =>
    batchUrlUpdates(() => {
      f.q.set(q)
      page.reset()   // one replaceState for both
    })

  return <input value={f.q()} onInput={(e) => search(e.currentTarget.value)} />
}

const tab = useUrlState('tab', 'overview')

const Tabs = () => (
  <nav>
    <button aria-pressed={() => tab() === 'overview'} onClick={() => tab.set('overview')}>Overview</button>
    <button aria-pressed={() => tab() === 'billing'} onClick={() => tab.set('billing')}>Billing</button>
  </nav>
)
// /settings            → overview
// /settings?tab=billing → billing
